namespace RonSijm.FluidHumidifier.Factories.AgentRegistry;

public class RegistryFactory(string resourceName = null, Action<Humidifier.AgentRegistry.Registry> factoryAction = null) : ResourceFactory<Humidifier.AgentRegistry.Registry>(resourceName)
{

    internal InnerRegistryApprovalConfigurationFactory ApprovalConfigurationFactory { get; set; }

    internal InnerRegistryEncryptionConfigurationFactory EncryptionConfigurationFactory { get; set; }

    internal InnerRegistryDiscoveryConfigurationFactory DiscoveryConfigurationFactory { get; set; }

    protected override Humidifier.AgentRegistry.Registry Create()
    {
        var registryResult = CreateRegistry();
        factoryAction?.Invoke(registryResult);

        return registryResult;
    }

    private Humidifier.AgentRegistry.Registry CreateRegistry()
    {
        var registryResult = new Humidifier.AgentRegistry.Registry
        {
            GivenName = InputResourceName,
        };

        return registryResult;
    }
    public override void CreateChildren(Humidifier.AgentRegistry.Registry result)
    {
        base.CreateChildren(result);

        result.ApprovalConfiguration ??= ApprovalConfigurationFactory?.Build();
        result.EncryptionConfiguration ??= EncryptionConfigurationFactory?.Build();
        result.DiscoveryConfiguration ??= DiscoveryConfigurationFactory?.Build();
    }

} // End Of Class

